export default [{"id":202,"question":"الزوجة المُطلَّقة إذا تزوجت وأنجبت بناتًا من الزوج الأخير، هل يجوز لهن أن يُسلمن على زوج أمهنَّ السابق في الوجه؟ ما الحكم في ذلك؟","title":"هل بنات المُطلَّقة محارم لزوجها الآخر؟","answer":"الجواب: نعم، محارم، إذا تزوَّج إنسانٌ امرأةً ودخل بها -لا بد من الدخول بها، يعني: إذا وطئها أو أنجبت بناتًا- ثم طلَّقها وتزوجت وجاءت ببناتٍ، فالبنات محارم له، ربائب، يُسلمن عليه، ويُسلم عليهنَّ، والأفضل أن يكون السلامُ في الخدِّ: خدّها، أو جبينها، أو أنفها، أو نحو ذلك، هذا هو الأفضل، أفضل من الفم. أما إذا تزوَّجها وطلَّقها ما دخل بها -عقد فقط وما دخل بها- فبناتها أجانب، ما يكن محارم له، لا من الزوج قبله، ولا من الزوج بعده.","link":"https://binbaz.org.sa/fatwas/3803/هل-بنات-المطلقة-محارم-لزوجها-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0209.mp3","categories":["المحرمات من النساء"]},{"id":555,"question":"الخلوة الكاملة تُحَرِّم البنت؟","title":"هل تحرم البنت بالخلوة بأمها أم الوطء؟","answer":"الجواب: لا ما تحرم بنتها إلا بالدخول، الدخول الوطء.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6386/هل-تحرم-البنت-بالخلوة-بامها-ام-الوطء","audio":"https://files.zadapps.info/binbaz.org.sa/maram121.mp3","categories":["المحرمات من النساء"]},{"id":557,"question":"تحريم الأم والجدة بالخلوة أو بالوطء؟","title":"هل تَحْرُم الأم والجدة بمجرد العقد؟","answer":"الجواب: الذرية بالوطء، أما الأم والجدة فهذا بمجرد العقد.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6388/هل-تحرم-الام-والجدة-بمجرد-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/maram123 - 01 -  Start.mp3","categories":["المحرمات من النساء"]},{"id":637,"question":"هل يجوز أن يكون والدي محرمًا لزوجتي لأداء العمرة وأنا في مدينة الرياض؟","title":"هل الأب محرم لزوجة الابن؟","answer":"الجواب: أبو الزوج محرم لها، نعم.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6564/هل-الاب-محرم-لزوجة-الابن","audio":"https://files.zadapps.info/binbaz.org.sa/maram205 - 01 -  Start.mp3","categories":["المحرمات من النساء"]},{"id":693,"question":"تقول في سؤالها الثالث: هل يجوز لابني أن يقبل خالتي؟","title":"هل يجوز تقبيل خالة الأم؟","answer":"الجواب: خالتك خالة له، أخت أمك، وأخت جدتك هي خالة له أيضًا، له أن يقبلها من رأسها، بين عينيها، في خدها، أما الفم تركه أولى، الفم يكون للزوجة والأطفال الصغيرة، أما تقبيل الكبيرة يكون في رأسها، أو بين عينيها، أو في خدها.","link":"https://binbaz.org.sa/fatwas/18955/هل-يجوز-تقبيل-خالة-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0044.mp3","categories":["المحرمات من النساء"]},{"id":963,"question":"رجلٌ تزوج بامرأةٍ وأنجب منها أولادًا، ولكن علم بعد ذلك أنها أخته من الرضاع، فما حكم زواجه بها؟ وماذا في الأولاد الذين أنجبتهم منه؟ أفيدونا جزاكم الله خيرًا.","title":"حكم من تزوجا وأنجبا ثم علما برضاعهما","answer":"الجواب: الأولاد أولاده، والاعتبار بالنكاح الشرعي الظاهر، وليس عليه في هذا إثمٌ ولا حرجٌ إذا كانوا ما قصَّروا ولا فرَّطوا؛ لكونهم علموا بعد ذلك أنها أخته من الرضاعة، لا يضرُّهم، الأولاد أولاده، وليس عليهم إثمٌ ما داما لم يعلما إلا بعد ذلك، الحمد لله، والله جلَّ وعلا لا يُؤاخذ بالجهالة، إنما يُؤاخذ بما تعمَّده الإنسان: رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، إذا كان ما تعمَّد الباطلَ فلا شيء عليه.\nس: يقول: يُطلِّقها؟\nج: يبطل النكاح... بطل النكاح، إذا علم أنها أخته بطل النكاح، لكن إذا طلَّقها طلقةً عن الشُّبهة طلَّقها طلقةً... إذا طلَّقها طلقةً يكون أحوط؛ خروجًا من الخلاف، يُطلِّقها طلقةً حتى يُعتمد عليها في تزويجها لغيره.","link":"https://binbaz.org.sa/fatwas/21005/حكم-من-تزوجا-وانجبا-ثم-علما-برضاعهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0802رجل تزوج بأمرأة وأجب منها أولاداً وعلم بعد ذلك أنها أخته من الرضاعة فما الحكم؟ ابن باز.mp3","categories":["الرضاع","المحرمات من النساء","مبطلات النكاح"]},{"id":1141,"question":"هل خال خالي يُعتبر محرمًا لي؟","title":"هل خالُ الخال من محارم المرأة؟","answer":"الجواب:\nما هو على كل حالٍ: إذا كان أخو الجدَّة فهو خالٌ لكِ، خال خالك صار أخو جدتك، وهي جدتك؛ يكون خالًا لك؛ لأنَّ خال المرأة خالٌ لأولادها، وعمَّها عمٌّ لأولادها، أما إذا كان خالًا لخالك لأنه أخٌ لأمه، وليس خال الخال أخًا لأمك؛ فلا يكون خالًا لكِ حتى يكون خالًا لك وخالًا لأُمِّك.\nفالمقصود إذا كان خالك وهو أخو أمك، وهذا خاله أخو جدة الجميع؛ لا بأس، يكون خالًا لكِ.","link":"https://binbaz.org.sa/fatwas/21191/هل-خال-الخال-من-محارم-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0987أمرأة تسأل هل خال خلي محرماً لي؟.mp3","categories":["المحرمات من النساء"]},{"id":3453,"question":"تَحْرُمُ الزوجة بمجرد العقد وإلا بالوطء...؟","title":"هل تَحْرُمُ الزوجة وابنتها بالعقد أم بالوطء؟","answer":"الجواب: لا، بالعقد، تَحْرُمُ بالعقد، وَأُمَّهَاتُ نِسَائِكُمْ [النساء: 23] بالعقد. وأما البنت لا، بالدخول، بالوطء لأمها، الربيبة ما تكون ربيبة إلا إذا وطء أمها، دخل بها.","link":"https://binbaz.org.sa/fatwas/23629/هل-تحرم-الزوجة-وابنتها-بالعقد-ام-بالوطء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حرمة النساء بالعقد، والربيبة بوطء أمها.mp3","categories":["المحرمات من النساء"]},{"id":3730,"question":"هل يحرم للمرأة أن تختلي بزوج ابنتها؟","title":"ما حكم خلوة المرأة بزوج ابنتها؟","answer":"الجواب: زوج ابنتها مَحْرَمٌ لها، لكن بعض النساء عندها شدة حياء كثير، والأوْلى ألا تحتجب منه، وأن تأخذ بالرخصة إن الله يحب أن تؤتى رخصه، فهذا يكون عيبًا في المرأة كونها تمتنع من محارمها.  أما إذا كان هناك سبب آخر بأنه رجل لا يُؤْمَن وأنه يفعل كذا وترى منه شيئًا ما يناسب؛ فهذا حقها أن تمتنع إذا كان له أسباب.","link":"https://binbaz.org.sa/fatwas/23922/ما-حكم-خلوة-المراة-بزوج-ابنتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خلوة المرأة بزوج ابنتها.mp3","categories":["النظر والخلوة والاختلاط","المحرمات من النساء","قضايا المرأة"]},{"id":5116,"question":"تقول في سؤالها الثالث: هل يجوز لابني أن يقبل خالتي؟","title":"هل يجوز تقبيل خالة الأم؟","answer":"الجواب: خالتك خالة له، أخت أمك، وأخت جدتك هي خالة له أيضًا، له أن يقبلها من رأسها، بين عينيها، في خدها، أما الفم تركه أوْلى، الفم يكون للزوجة والأطفال الصغيرة، أما تقبيل الكبيرة يكون في رأسها، أو بين عينيها، أو في خدها.","link":"https://binbaz.org.sa/fatwas/30024/هل-يجوز-تقبيل-خالة-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 44.mp3","categories":["المحرمات من النساء"]},{"id":5303,"question":"هل يجوز للمرأة أن تكشف على زوج ابنتها بعد الطلاق من ذلك الرجل؟","title":"هل تظل المرأة محرمًا لزوج ابنتها بعد الطلاق؟","answer":"الجواب: نعم، محرم لها ولو ماتت بنتها ولو طلقت، زوج البنت وزوج الأم محرم ولو ماتت الأم ولو ماتت البنت ولو طلقت؛ فزوج البنت محرم لها، قال الله: وأمهات نسائكم...[1]","link":"https://binbaz.org.sa/fatwas/30953/هل-تظل-المراة-محرما-لزوج-ابنتها-بعد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 023.mp3","categories":["المحرمات من النساء"]},{"id":5334,"question":"في حديث الرسول ﷺ: لا يجمع الرجل بين المرأة وعمتها ولا بين المرأة وخالتها فهل يجوز أن يكشف الرجل على عمة امرأته أو خالتها، وإذا كان لا يجوز فما معنى هذا الحديث؟","title":"حكم جمع الرجل بين المرأة وعمتها أو خالتها","answer":"الجواب: لا يجمع بينهما في النكاح، لا يجمع بين المرأة وعمتها، ولا بين المرأة وخالتها، أي ليس له أن يتزوج فاطمة مع عمتها خديجة مثلًا، أو خالتها، لا هذه ولا هذه، لا الكبرى على الصغرى ولا الصغرى على الكبرى، إذا كان معه فاطمة ولها عمة أو خالة لا يتزوجهما معًا، أو لها بنت أخ أو بنت أخت لا يتزوجهما معًا، لا يجمع بينهما. أما بنات العم لا بأس، بنات الخال لا بأس يجمع بينهما، أما امرأة وخالتها أو امرأة وعمتها لا يجوز الجمع بينهما في النكاح، في الزواج يعني.[1]","link":"https://binbaz.org.sa/fatwas/31008/حكم-جمع-الرجل-بين-المراة-وعمتها-او-خالتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 056.mp3","categories":["المحرمات من النساء"]},{"id":5973,"question":"هل يجوز الزواج من زوجة والد زوجتي، أم لا؟","title":"حكم الزواج بزوجة والد الزوجة","answer":"الجواب: نعم، يجوز أن يتزوج زوجة والد زوجته إذا كانت ما هي أمها أجنبية، ما بينهم رضاع، ولا شيء؛ فيجمع بين امرأة، وبين زوجة أبيها التي ليست أمها، تزوج عبدالله بن جعفر من ابنة علي -رضي الله عنهم- التي ليست هي أمها.  المقصود: أنه لا بأس أن يجمع بين امرأتين، إحداهما زوجة أبي الأخرى.","link":"https://binbaz.org.sa/fatwas/1359/حكم-الزواج-بزوجة-والد-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_317.mp3","categories":["المحرمات من النساء","الآداب والأخلاق"]},{"id":6042,"question":"هل تقبيل امرأة الولد من أبيه جائز، ولو هي أجنبية عنه في المناسبات، مثل الأعياد، والسفر، أقصد أجنبية ليست أخته، أو أخيها؟","title":"حكم تقبيل زوجة الابن","answer":"الجواب: زوجة الولد محرم لا حرج، زوجة الولد، زوجة ولده، وزوجة ولد ولده، وزوجة ابن ابنته، وزوجة أبيه، وجده كلهم محارم، الله قال: وَلَا تَنْكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ إِلَّا مَا قَدْ سَلَفَ [النساء:22] وقال: وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ [النساء:23].  فأولاده من صلبه، وأولاده من الرضاع، زوجاته محارمه، فإذا قبلته، أو قبلها لا عن شهوة، ولكن في المناسبات مثل الأعياد، وعند قدوم من سفر؛ فلا حرج في ذلك، ولكن الأفضل أن يكون التقبيل إن قبلته تقبله على أنفه، وعلى رأسها، وإن قبلها يكون في خدها، أو على رأسها، هذا هو الأفضل، لا مع الفم ، مع الفم الأولى تركه للزوج، هذا هو الأولى عند جمع من أهل العلم.","link":"https://binbaz.org.sa/fatwas/1451/حكم-تقبيل-زوجة-الابن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_379.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":6044,"question":"زنى رجل بامرأة، فحملت بالحرام، ثم ذهب إلى أبيها، وطلب الزواج منها، وتم له العقد عليها، وتزوج وهي حامل في ثلاثة شهور، السؤال ما حكم هذا النكاح؟ وما مدى صحة عقده؟ وهل عيالهم شرعيين، أم لا؟","title":"حكم نكاح الزاني بمن زنى معها حال حملها","answer":"الجواب: ما يصح النكاح مع الحمل من الزنا حتى تتوب، حتى تخرج من عدة هذا الزنا الفاسد، حتى تستبرأ بحيضة، وتتوب، ثم يزوجها بعد ذلك . السؤال: ولو كان منه؟ الجواب: ولو، لأن هذا الحمل لا يلحقه، زنا لا ينسب إليه، ثم الزانية لا بدّ أن تستتاب، ويتوب هو؛ لأنه لا ينبغي أن يتزوجها إلا بعد أن يظهر منها التوبة، وهو كذلك ليس بكفء حتى يظهر منه التوبة، فهذا على كل حال ينبغي فيه استتابة الجميع.","link":"https://binbaz.org.sa/fatwas/1464/حكم-نكاح-الزاني-بمن-زنى-معها-حال-حملها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_394.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":6046,"question":"سمعت أنه لا يجوز للرجل أن يقبل من محارمه إلا زوجته حتى أخته، وابنته، لا يقبلها ؟","title":"حكم تقبيل المحارم","answer":"الجواب: هذا لا أصل له، لا بأس أن يقبل محارمه، وأمه، وخالته، وأخته، هذا لا حرج في ذلك، ولكن إذا قبل أخته أو بنتها مع خدها أو أنفها أو رأسها؛ حسن، الفم تركُه أوْلى.","link":"https://binbaz.org.sa/fatwas/1465/حكم-تقبيل-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_395.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":6097,"question":"هل زوج الأخت يعتبر محرمًا للأخت الأخرى مؤقتًا، بحيث يجوز أن يختلي بها، وكذلك عمة البنت؟","title":"هل التحريم المؤقت يكون سبباً للمحرمية","answer":"الجواب: لا، زوج الأخت ليس محرمًا لها، زوج الأخت، ونحوه، وكذلك العمة لا تكون العمة التي يحرم عليه نكاحها على البنت، وهكذا خالتها إنما هذا تحريم مؤقت، فلا يكون محرمًا زوج أختها، وهكذا زوج عمتها، وهكذا زوج خالتها، وهكذا نفس العمة، عمة الزوجة، وأخت الزوجة، وخالة الزوجة ليست من المحارم للزوج؛ لأنهن محرمات عليه، فإذا طلق أختهن، أو بنت أخيهن، أو بنت أختهن؛ جاز له النكاح بعد العدة. فالحاصل: أن بعض النساء تتساهل مع زوج أختها، ويتساهل بعض الناس مع أخي زوجها، ومع عم زوجها، وهذا غلط لا يجوز، لا يجوز للمرأة أن تتساهل مع أخي زوجها، ليس محرمًا لها، وليس عمه محرمًا له، ولا خاله. وإنما المحرم أبوه، أبوه، ووالده هم المحارم، أما أخو الزوج، وعم الزوج، وابن عم الزوج، وخال الزوج ليسوا محارم .. زوج الأخت، وزوج العمة، وزوج الخالة ليسوا محارم، المحرم زوج بنتها، وزوج أمها، هذا هو المحرم، أما زوج أختها، أو زوج عمتها، أو زوج خالتها فليسوا محارم، يجب الحجاب، والتحرز، وعدم الخلوة.","link":"https://binbaz.org.sa/fatwas/1511/هل-التحريم-الموقت-يكون-سببا-للمحرمية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_441.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":6282,"question":"خطبت بنتًا ثم فسخت الخطبة وتزوجت أمها فما رأي سماحتكم هل هذا حلال أم حرام؟","title":"حكم الزواج بأم من فسخت خطوبتها","answer":"الجواب:  إذا خطب امرأة ثم ترك الخطبة وتزوج أمها لا بأس، أما إذا عقد عليها تم العقد حرمت أمها، أما إذا كان ما تم العقد وكانت مجرد خطبة فقط ثم هون وأخذ الأم لا بأس.","link":"https://binbaz.org.sa/fatwas/1793/حكم-الزواج-بام-من-فسخت-خطوبتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_632.mp3","categories":["المحرمات من النساء","شروط وأركان الزواج"]},{"id":6560,"question":"لي أخ من أبي، وله أخت من أمه، وقد تزوجها عمي، فهل يجوز لي مصافحتها؟","title":"حكم مصافحة الأخ أخت أخيه من أمه","answer":"الجواب:\n\nلا، أجنبية عنك، أخت أخيك من أمك لا، ما هي بأخت لك، أجنبية، وزوجة عمك أجنبية، ولكن تسلم عليها مع الحجاب، أما المصافحة فلا، لا بد من الحجاب، وعدم المصافحة، إنما تسلم عليها بالكلام، كيف حالك يا فلانة؟ كيف أولادك؟ كيف أبيك؟ ما في بأس.\n\nأما المصافحة لا، إلا مع المحرم، مع أختك، مع عمتك، خالتك، أمك ما يخالف، زوجة أبيك، زوجة جدك، زوجة ولدك لا بأس، أما زوجة عمك، وزوجة خالك لا، أجنبية.","link":"https://binbaz.org.sa/fatwas/2419/حكم-مصافحة-الاخ-اخت-اخيه-من-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_946.mp3","categories":["الآداب والأخلاق","المحرمات من النساء"]},{"id":6891,"question":"فتاة وفتى رضعا من عمتهم، هل يجوز للفتى أن يتزوج بهذه الفتاة؟","title":"حكم زواج الرجل بفتاة اشترك معها في الرضاعة من امرأة","answer":"الجواب: إذا اجتمع فتى وفتاة في الرضاع من أي امرأة كانت؛ صارا أخوين، سواء كانت عمتهم، أو صارت ابنة عمهم، أو بعيدة منهم، إذا اجتمعا في الرضاع من أي امرأة؛ فإنهما يكونان أخوين إذا تم الرضاع الشرعي، إذا كان الرضاع خمس رضعات، فأكثر في الحولين، فإنهما يكونان أخوين، وإن كانت المرضعة أجنبية منهما بالكلية، يكونا أخوين، ليس له أن ينكحها؛ لأنها صارت أخته بالرضاع، إذا كان الرضاع خمس رضعات، فأكثر، وكان رضاعهما في الحولين، لا بعدهما، هذا هو الذي جاءت به الشريعة عن النبي -عليه الصلاة والسلام-.","link":"https://binbaz.org.sa/fatwas/2767/حكم-زواج-الرجل-بفتاة-اشترك-معها-في-الرضاعة-من-امراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1259.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7466,"question":"هنا سؤال من السائل (ع. ت. س) يقول: عقد رجل على امرأة فطلقها قبل أن يدخل بها، فهل تجوز لابنه من بعد طلاقه لها؟","title":"حكم زواج الابن بزوجة أبيه المطلقة قبل الدخول بها","answer":"الجواب: لا، إذا طلق الرجل امرأة حرمت على جميع ذريته؛ من أولاده وأولاد بنيه وأولاد بناته؛ لأنها زوجة أبيهم وإن لم يدخل بها؛ لأن الله ما علق .... بالدخول، قال سبحانه: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ إِلَّا مَا قَدْ سَلَفَ [النساء:22] فحرم نكاح زوجات الآباء مطلقاً، والأب يدخل فيه أبوه القريب وجده وأبو أمه وآباء أمه كلهم؛ كل آبائه من جهة الأم ومن جهة الأب، زوجاتهم محرمة عليه وهو محرم لهم في الآية الكريمة وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ [النساء:22] هذا يعم المدخول بها وغير المدخول بها، وهذا محل إجماع عند أهل العلم ليس فيه خلاف.\nوهكذا العكس؛ الابن، حلائل الأبناء يحرمن على الآباء مطلقاً، ولو لم يدخل بها الابن، إذا تزوج رجل امرأة ثم مات عنها قبل الدخول بها أو طلقها قبل الدخول بها حرمت على آبائه وأجداده كلهم؛ لأن الله قال: وَحَلائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلابِكُمْ [النساء:23] ولم يقل: اللاتي دخلتم بهن. نعم.","link":"https://binbaz.org.sa/fatwas/4187/حكم-زواج-الابن-بزوجة-ابيه-المطلقة-قبل-الدخول-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_002/00203.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7467,"question":"يقول: هل يجوز للرجل أن يقبل أخته أو بعض محارمه مثل تقبيله لزوجته، مع أن هذا منتشر في بعض الجهات؟","title":"حكم تقبيل الرجل محارمه كتقبيله زوجته","answer":"الجواب:  يجوز للإنسان أن يقبل محارمه؛ مثل أخته وعمته وخالته، لا حرج في ذلك، قد ثبت أن الصديق  دخل على ابنته عائشة وقد كانت تعاك، أصابها بعض الحمى فقبلها مع خدها، فالتقبيل جائز لكن لا يكون مع الفم، الأولى أن لا يكون مع الفم، الفم يكون للزوجة أو السرية، أما تقبيل المحارم فالأولى والأحوط أن يكون مع الخد مع الأنف مع الرأس، هذا هو الأولى؛ لأنه أبعد عن الفتنة والشهوة. نعم.","link":"https://binbaz.org.sa/fatwas/4192/حكم-تقبيل-الرجل-محارمه-كتقبيله-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_002/00204.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":7490,"question":"سماحة الشيخ! أول سؤال في هذا اللقاء وردنا من اليمن، من أحد الإخوة الذي رمز باسمه بـ (ش. ف. ك) يقول: إذا تزوج رجل امرأة ثم ثبت أن جدتها أم أمها أرضعته سنة كاملة بلبن خفيف وهي عجوز، قد مات زوجها لمدة طويلة، فهل يبطل هذا النكاح؟ أفتونا مأجورين.","title":"حكم من تزوج بامرأة ثم ثبت أن جدتها أرضعته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفقد ثبت في الكتاب العزيز والسنة المطهرة: أن الرضاع يحرم به ما يحرم من النسب، وقد بين الله في كتابه الكريم تحريم الأمهات من الرضاع والأخوات من الرضاع، وقد ثبت في السنة عن رسول الله عليه الصلاة والسلام أنه قال: يحرم من الرضاع ما يحرم من النسب فعم ذلك جميع المحرمات من النسب، فالأم من الرضاع، والبنت من الرضاع، والأخت من الرضاع، وبنت الأخ من الرضاع، وبنت الأخت من الرضاع، والعمة من الرضاع، والخالة من الرضاع، كلهن محرمات، كما أنهن محرمات من النسب، بنص رسول الله عليه الصلاة والسلام، فهذه المسألة التي ارتضع فيها إنسان من جدة زوجته؛ أم أمها يكون بذلك خالاً لها أخا أمها، إذا كان أرضعته العجوز سنة كاملة، بل يكفي أنها أرضعته خمس رضعات، إذا أرضعته خمس رضعات ولو في مجلس واحد فإنه يكون بذلك خالاً لزوجته؛ أخاً لأمها، فتحرم عليه؛ لأن بنت الأخت حرام من النسب، فهكذا تكون حرام من الرضاع بنص الرسول عليه الصلاة والسلام وبإجماع أهل العلم، ولو أنها عجوز كبيرة، ولو أنها ليست ذات بعل قد مات بعلها من مدة طويلة، فإن ظهور اللبن فيها يحرم من أرضعته به، فتكون هذه الزوجة بنت أخت الزوج، ويكون خالها، فتحرم عليه بذلك، وتكون العجوز أماً لهذا الزوج وجدة لأولاده من هذه الزوجة ومن غيرها؛ لأنه صار ولداً لها، بهذا الرضاع، ولو أنه خفيف ما دام لبناً يغذيه يتغذى به، فإنه يحرم به ما يحرم من النسب، ولو أنها ليست ذات بعل في الوقت الحاضر، حتى ولو كانت شابة على الصحيح؛ لم توطأ ولم تحمل، إذا درت باللبن وأرضعت صار أماً للرضيع، وصار إخوتها أخوالاً له، وخواتها خالات له، واشتراط أن تكون المرأة قد حملت ليس بجيد، أو وطئت ليس بجيد، أما هذه التي قد حملت وولد لها وقد مات بعلها من قديم، هذه تامة فيها الشروط عند أهل العلم، فقد حملت وقد ولدت، فهي على كل حال لبنها مؤثر، ولو أنها قد مات زوجها من مدة طويلة، فهذا اللبن الذي أرضعت به هذا الرجل يكون به خالاً لزوجته، فتحرم عليه زوجته. نعم.","link":"https://binbaz.org.sa/fatwas/4451/حكم-من-تزوج-بامراة-ثم-ثبت-ان-جدتها-ارضعته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_006/00601.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7641,"question":"هذه رسالة وردتنا من مرسلها محمد بن علي سلمان يقول: صاحب الفضيلة الرئيس العام لإدارات البحوث العلمية والإفتاء والدعوة والإرشاد، سماحة الشيخ عبد العزيز بن عبد الله بن باز الموقر، السلام عليكم ورحمة الله وبركاته، الموضوع أحسن الله عملك أنا محمد بن علي سلمان الأحمدي المالكي من قضاء بني مالك تابع لجيزان، جزاكم الله خير الجزاء لما لكم من فعل الخير وإيضاحه وطمس الشر ومعالمه، لي أخ من الرضاعة وله ثلاث بنات، هن: معزيه بنت حسن وفاطمة بنت حسن ، وجميلة بنت حسن بن سالم بن قاسم ، وأخي المذكور متوفى قبل والده، وصرنا عصبة، هل البنات لي محرم، وأجوز لهن محرم أم لا؟ أفتوني بهذا الأمر وفقكم الله، وسدد خطاكم بحفظه ورعايته، والرجاء أن تتكرموا بإذاعة هذه الفتوى في برنامج نور على الدرب، والله يرعاكم؟","title":"حكم بنات الأخ من الرضاع","answer":"الجواب: إذا كان أخو السائل قد ارتضع من أم السائل خمس رضعات فأكثر، أو السائل ارتضع من أمه وهو حسن هذا، إذا ارتضع من أمه خمس رضعات فأكثر فإنه يكون أخاه، وتكون بناته بنات أخ من الرضاعة محارم، فإذا تحقق هذا بأن كانت أم السائل أرضعت حسن المذكور فإنه يكون أخاه من الرضاعة، أو زوجة أبيه أرضعت حسن المذكور خمس رضعات فأكثر، أو أم حسن أرضعت السائل خمس رضعات فأكثر، فإن السائل يكون أخاً لـحسن هذا، ويكون عماً لبناته وعماً لبنات بناته وهكذا، يكون عم ويكون هو عمهن من الرضاع، ويكون محرماً لهن؛ لقول النبي عليه الصلاة والسلام: يحرم من الرضاع ما يحرم من النسب.\nأما إن كانت الرضعات أقل من خمس أو كانت الرضعات فيها شك لا يدرى هل ارتضع أم لم يرتضع، وإنما يقال: إنه أخوه من الرضاعة من غير جزم، هذا لا يكن محارم للسائل، ولا يكون عماً لهن إلا برضاع ثابت، بشهادة المرضعة الثقة أو شهادة غيرها من الثقات أن أم حسن أرضعته أو أن أمه أرضعت حسن ، فصار أخاً له أو زوجة أبيه، أو زوجة أبي حسن أرضعته، هذا هو الحكم في هذه المسألة.\nفالواجب التثبت في الأمر، حتى إذا ثبت الرضاع فإنه يكون عماً لبنات حسن المذكور، وهكذا بناتهن وبنات أولادهن هو عمهن.","link":"https://binbaz.org.sa/fatwas/4774/حكم-بنات-الاخ-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_035/03502.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7794,"question":"وسماحة الشيخ! نبدأ برسالة عبد الله بن حسين الحسين من حوطة بني تميم أسفل الباطن التي يقول فيها:إلى حضرة الشيخ العزيز الغالي عبد العزيز بن باز .. حفظه الله ورعاه تحية طيبة وبعد..أرفع إليكم سؤالي هذا راجياً منكم التكرم بالإجابة عليه، يقول: (س) تزوجت امرأة اسمها حصة وأتت ببنت اسمها نورة ، ثم توفي زوج حصة وتزوجت رجلاً آخر وأتت منه ببنت اسمها هند ، وتزوجت نورة وأتت أيضاً ببنت، وقامت نورة بإرضاع بنت أمها التي هي هند ، ثم توفي زوج نورة وتزوجت رجلاً آخر، فهل يصح لـهند أن تكشف لزوج أمها من الرضاعة وأختها من أمها علماً بأن هند ، رضعت من لبن الرجل نورة الأول وشكراً؟","title":"زوج الأم من النسب والرضاع محرم للبنت","answer":"الجواب: أي: صارت بنتاً لها، هند هذه التي هي أخت نورة إذا كانت نورة أرضعتها رضاعاً كاملاً وهو خمس رضعات فأكثر في الحولين، فإن هند تكون بنتاً لـنورة بنتاً لأختها الكبرى ويكون زوج نورة الجديد يكون محرماً لـهند لأنه زوج أمها بالرضاعة، فـنورة هذه تزوجت زوجاً أخيراً يكون بالنسبة إلى هند التي هي أختها يكون زوجاً لأمها من الرضاعة فيكون محرماً لها؛ لأن زوج الأم من النسب والرضاع محرم للبنت، وهند بموجب السؤال صارت بنتاً لأختها نورة الكبرى من الرضاعة، وزوج نورة يكون حينئذٍ زوج أم هند سواء كان زوجها الأول أو زوجها الآخر، المقصود: إنها صارت بنتاً لأختها نورة ، فأزواج نورة كلهم يكونون محارم زوجها الموجود أو زوجها الذي يأتي بعده، أزواج نورة أزواج لأم هند ، فتكون هند محرماً، فتكون هند محرماً لهم وهم محرم لها بسبب الرضاع، لكن بشرط أن يكون الرضاع خمس رضعات فأكثر، يعني: تكون نورة أرضعتها خمس مرات أو أكثر من خمس مرات حال كون هند في الحولين، إذا تم هذا الشرط فإن أزواج نورة يكونوا محارم لأختها هند بموجب الرضاعة. نعم.","link":"https://binbaz.org.sa/fatwas/5144/زوج-الام-من-النسب-والرضاع-محرم-للبنت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05001.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7795,"question":"المقدم: وهذا آخر سؤال فيه رسالة هذه أخرى ملاصقة للرسالة هذه هذا بعثها المرسل من بحرة عبد الرحمن محمد حزام الشيباني يقول: الحمد لله، والصلاة والسلام على أشرف المرسلين.أما بعد:أفيدوني أفادكم الله أن والدي تزوج ابنة عمه شقيقته وأخذت في حبله خمس سنوات ولم تنجب أحد فطلقها فتزوج بعدها زوجة أخرى وهي والدتي، فهل يجوز لي السلام عليها -يعني: على زوجة والده الأولى- لأنها عمتي زوجة والدي سابقاً، فهل يجوز لي السلام أم لا أفيدوني أفادكم الله وأطال في أعماركم؟","title":"حكم النظر والمصافحة لزوجة الأب بعد تطليقها","answer":"الجواب: نعم، زوجة أبيك محرم لك سواء أنجبت أم لم تنجب، زوجة أبيك -أيها السائل- محرم لك سواء أنجبت من أبيك أم لم تنجب ولو عقد عليها فقط عقداً مجرداً ولم يدخل بها فإنها محرم لك؛ لأن الله قال: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ [النساء:22] فزوجات الآباء والأجداد محارم لمجرد العقد، فإذا لم يدخل بها جدك أو أبوك فهي محرم لك، وإن دخل بها واجتمع بها فمن باب أولى أنها محرم لك وإن لم تنجب.\nفالخلاصة: أن زوجات الآباء والأجداد محارم سواء أنجبن من آبائك وأجدادك أم لم ينجبن، والله جل وعلا أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/5158/حكم-النظر-والمصافحة-لزوجة-الاب-بعد-تطليقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05007.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7796,"question":"أيضاً يقول المستمع عبد الله بن حسين الحسين من حوطة بني تميم: امرأة لها بنات ابن، فلما توفي زوجها -أي: الذي هو جد البنات- تزوجت رجلاً آخر، فهل يصح لبنات ابنها أن تكشف لزوجها الأخير؟","title":"حكم كشف البنات لزوج جدتهن","answer":"الجواب: إيه، لأنه زوج جدتهم، زوج الجدة وزوج الأم محرم، زوج الجدات وزوج الأم محرماً لبنات الابن وبنات البنت محرماً لهم بموجب الرضاع، وكذلك لأن هنا هم أولاد نسب ليسوا برضاع، وهي أم أبيهم من النسب ولو كانوا من الرضاعة كذلك.\nفالحاصل أنه محرم لهم، زوج الجدة محرم لأولادها وأولاد بناتها، وأولاد ابنها من جميع الوجوه سواء كانوا أولاداً من النسب أو أولاداً من الرضاعة. نعم.","link":"https://binbaz.org.sa/fatwas/5148/حكم-كشف-البنات-لزوج-جدتهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05002.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7996,"question":"ونبدأ برسالة المواطن إقليل علي حيث يقول في رسالته: السلام عليكم ورحمة الله وبركاته.وبعد: هو أننا في تبالة بلاد الفزع شمران، والتي تقع غرب مدينة بيشة، لدينا مذاهب وهي قديمة من على إثر الأولين، وهي أن نساء القبيلة لا يتغطين من رجال القبيلة سواء من أقاربهم أو من غيرهم، وحيث أنني -أنا السائل- أفهم أن هذا الإجراء ليس مشروعاً في السنة والكتاب ولكن لم أقدر على إلغاء هذه المذاهب المخالفة للسنة، فماذا يلحق المحتار في عدم مشاهدة النساء اللاتي من غير محرم وهن كاشفات، أفيدوني أفادكم الله، وكما أفيدكم أنه لم يسبق أن حصل في تلك البلاد إرشاد يعلمهم الصحيح والمتبع لدى كثير من المسلمين وفقكم الله؟","title":"حكم عدم احتجاب المرأة من رجال قبيلتها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: الواجب عليك وعلى غيرك إرشادهم وتعليمهم وتحذيرهم من هذا، تقول لهم: يا أمة الله.. يا فلانة! هذا لا يجوز، الواجب عليكن الاحتجاب عن غير المحارم، إذا كن يكشفن لغير المحارم من رجال القبائل، على أوليائهن أن يعلموهن أن هذا لا يجوز، والله أمر بالحجاب، كما في قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فالحجاب طهارة لقلوب الجميع، الرجال والنساء، وأبعد لهم جميعاً عما حرم الله.\nفأنت عليك أن تغض بصرك، وأن تنكر المنكر وتعلم من استطعت من نساء قومك، وكذلك من يسمع كلامي هذا من رجال القبيلة، عليهم أن يتآمروا بالمعروف ويتناهوا عن المنكر وأن يجتهدوا في منع نسائهم من التكشف والسفور لغير محارمهن هذا الواجب على الجميع من باب التعاون على البر والتقوى، والسكوت عن هذا من باب التعاون على الإثم والعدوان، فالواجب على رجال القبيلة في هذه الجهة في هذه المنطقة أن يتعاونوا على البر والتقوى وأن يعلموا نساءهم الاحتجاب عن غير المحارم، وأن ينكروا على من تساهلت في ذلك حتى تعم الفائدة، وحتى يقل هذا المنكر، وأنا -إن شاء الله- سوف أبلغ الجهات المسئولة عندنا في رئاسة البحوث العلمية والإفتاء حتى يعمدوا الدعاة إلى الله في بيشة وفيما حولها بالعناية بهذا الأمر والتجول في هذه المنطقة، وإرشاد أهلها إلى ما ينفعهم في دينهم ودنياهم، ولا سيما ما يتعلق بالعقيدة وأمر الصلاة وأمر الحجاب، وما أشبه ذلك مما قد يحصل به التساهل، نسأل الله للجميع الهداية. نعم.","link":"https://binbaz.org.sa/fatwas/5552/حكم-عدم-احتجاب-المراة-من-رجال-قبيلتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_074/07401.mp3","categories":["قضايا المرأة","المحرمات من النساء"]},{"id":8003,"question":"هذه رسالة بعث بها حمود بن سليمان بن سلمان الجهني من مرور المدينة المنورة، يقول في رسالته: قبل أن أبث لكم برسالتي أود تبليغ شكري وتقديري إلى القائمين بهذا البرنامج وإلى فضيلة العلماء والمشايخ الذين يجيبون على رسائل المستمعين.يقول عنده مشكلة رضاع، يقول: أفيدكم أنني من تاريخ ولادتي توفت والدتي، وكنا من سكان البادية وأخذوا يطعمونني من ألبان الإبل والغنم، ثم قامت جدتي أم والدي برعايتي وحن قلبها إلي، وأرضعتني من نفسها، وبعد ذلك مضت الأيام وكبرت وكان لأبي إخوان من أمه وأبيه، ولديهم بنات، وأردت أن أتزوج من أحد إحداهن، فهل تحل لي أم لا، أفيدوني جزاكم الله عنا خيرا وتقبلوا تحياتي؟","title":"حكم من رضع من جدته ويريد الزواج بإحدى بنات عمه","answer":"الجواب: إذا كانت جدة السائل قد أرضعته رضاعاً تاماً خمس رضعات فأكثر حال كونه في الحولين فإنه يكون أخاً لأبيه وأعمامه، وعماً لبنات أعمامه، فلا يحل له أن ينكح منهن أحداً؛ لأنه صار عماً لهن بالرضاع، فلابد من التثبت في هذا الأمر، فإذا كانت الجدة قد در لها لبن أرضعتك منه -أيها السائل- خمس مرات يعني: خمس رضعات فأكثر حال كونك في الحولين فإنها تكون أمك من الرضاعة وتكون أنت أخاً لأبيك وأعمامك من الرضاعة، وعماً لبنات أعمامك من الرضاعة، فلا يحل لك نكاح أحد منهن، والله سبحانه وتعالى أعلم.","link":"https://binbaz.org.sa/fatwas/5569/حكم-من-رضع-من-جدته-ويريد-الزواج-باحدى-بنات-عمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_075/07502.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":8781,"question":"الرسالة الثالثة في هذه الحلقة وردتنا من السودان من بور سودان من السائل أوهاج محمد حمد ، يقول في رسالته: هناك رجل كان على صلة بامرأة بغير زواج فأنجب منها طفلة وافترقا فترة طويلة، ثم تقدم لخطبة بنت تعرف عليها ووافقت على الزواج منه فتزوجها وبعد فترة اكتشف أنها بنته الغير شرعية من تلك المرأة، فما حكم الإسلام في ذلك؟ وماذا يفعل؟","title":"حكم من تزوج بابنته غير الشرعية بدون علم","answer":"الجواب: أولاً: عليه التوبة مما جرى منه من الزنا والرجوع إلى الله والندم والإقلاع والصدق في ذلك وكثرة الاستغفار والعمل الصالح.\nثانياً: هذا النكاح باطل، ما دام عرف أنها ابنته من الزنا فالذي عليه جمهور أهل العلم أنه نكاح باطل؛ لأنها خلقت من مائه فلا يجوز له نكاحها، وإن كانت غير شرعية بنت غير شرعية، لكنها تدخل في عموم قوله جل وعلا: حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُم [النساء:23] هي بنت غير شرعية خلقت من مائه فيكون نكاحها باطلاً ولا تنسب إليه، ولا تكون محرماً له، لكن نكاحها باطل عند أهل العلم؛ لأنها خلقت من مائه غير الشرعي فيحرم عليه نكاحها ولا تنسب إليه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6934/حكم-من-تزوج-بابنته-غير-الشرعية-بدون-علم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21907.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":8783,"question":"يسأل أيضاً ويقول: هناك رجل تزوج امرأة ثم غاب فترة طويلة استمرت سنين، فلما طال غيابه عنها تزوجت المرأة من رجل آخر فأنجبت منه طفلين وبعد ذلك حضر الزوج الأول، فما الحكم في هذه الحالة؟ وإذا كان طلاق المرأة من الرجل الثاني وزواجها من الأول باطل فلمن يكون الأبناء، للرجل أم للمرأة، أفيدونا بارك الله فيكم؟","title":"حكم الزواج من زوجة رجل غائب دون فسخ من القاضي","answer":"الجواب: هذه المرأة التي تزوجت إن كانت تزوجت من غير فسخ من الحاكم ولا طلاق من زوجها فنكاحها باطل، وأولادها أولاد شبهة يلحقون بزوجها الذي تزوجها بغير وجه شرعي؛ لأنهم ولدوا على شبهة، الزوج الثاني الذي نكحته أولاده تابعون له؛ لأنه نكاح شبهة، ولكنه باطل لأنه حصل من دون طلاق من الزوج ولا فسخ من المحكمة، بل هذا جرأة منها وتساهل منها فبطل، ولكن الأولاد حصلوا عن شبهة وعن ظن الزوج أن هذا الزواج صحيح فينسبون إليه ويحكم له بهم إذا كان الأمر هكذا عن شبهة وعن ظن أن زواجه بها صحيح، أما إن كان قد تعمد وطأها باسم النكاح وهو يعرف أنه نكاح باطل وأنها غير مطلقة وأن الحاكم ما فسخها، بيعلم هذا كله هذا زنا، يقام عليه حد الزنا وأولاده ينسبون إلى المرأة، لا ينسبون إليه، أما إذا كان تزوجها ظناً أنها مخلوعة أو أنها مطلقة ما درى أنها مع الزوج، فهذا نكاحه باطل ولكن أولاده يلحقون به لأجل الشبهة.\nوأما الزوج الذي قدم بعد ذلك وهي لم تفسخ منه ولم تطلق منه فهذا باق على النكاح هي زوجته تفسخ من هذا الزوج الذي أخذها بغير حق وتعتد، فإذا اعتدت من هذا الزوج الذي نكحها بشبهة تعود إلى زوجها الأول؛ لأن نكاحه باقي لم يفسخ ولم يحصل منه طلاق.\nفالحاصل المسألة هذه مسألة كبيرة، والواجب أن تحل من جهة المحكمة حتى يؤدب هذا الزوج الذي أخذها بغير حق إذا كان الأمر كما قاله السائل، فإنه يستحق أن يؤدب بكل حال لأنه ما تثبت في الأمر، وإن كان يعلم أنها مزوجة وأنها ذات زوج ثم أقدم على نكاحها باسم نكاح باطل فهذا يستحق أن يقام عليه الحد حد الزنا، إن كان محصناً يرجم، وإن كان بكراًَ يجلد مائة جلدة ويغرب عاماً.\nفالحاصل: أن هذه مسألة مهمة يجب أن تحال إلى المحكمة حتى تنظر فيها المحكمة وحتى تحقق فيها وحتى تعمل ما يقتضيه الشرع المطهر. والله المستعان.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6935/حكم-الزواج-من-زوجة-رجل-غاىب-دون-فسخ-من-القاضي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21908.mp3","categories":["شروط وأركان الزواج","المحرمات من النساء"]},{"id":9475,"question":"أولى الرسائل في حلقة الليلة وردتنا من المستمعة (ح. غ) من المملكة، تقول في رسالتها: أنا أحاول أن أطبق تعليمات ديننا الحنيف من صلاة وصيام ومحافظة على الحجاب عن غير المحارم، إلا أنني أكشف عن وجهي ويدي وما يظهر عادة للمحارم لجد زوجي، فهل هو منهم أفيدوني أفادكم الله؟","title":"حكم محرمية جد الزوج بالنسبة للزوجة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فجزاك الله خيراً على اهتمامك بالدين وحرصك على المحافظة على ما أوجب الله عليك.\nأما السؤال عن جد الزوج فلاشك أنه محرم، جد الزوج أبو أبيه أو أبو أمه كلهم محارم، فلا بأس عليك بالكشف له كالوجه واليدين ونحو ذلك، كل هذا لا حرج فيه كسائر المحارم، كأخيك وعمك ونحو ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7636/حكم-محرمية-جد-الزوج-بالنسبة-للزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24101.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":9588,"question":"يسأل أيضاً ويقول: هناك من العوام من يعتقد أن من أنقذ طفلاً أو طفلة غريقة تكون بنتاً له ولا يصح له الزواج منها، وإن كانت ولداً فتكون ولداً له. أفيدونا عن صحة هذه المقولة بارك الله فيكم؟","title":"هل تثبت المحرمية لمن أنقذ طفلة من الغرق؟","answer":"الجواب: هذا من خرافات العامة، هذا وأشباهه من خرافات العامة ومن أكاذيبهم التي يقولونها بغير حجة، فلو أنقذ إنسان طفلة من غرق أو حرق أو غيرهما فإنه لا يكون محرماً لها إذا كانت أجنبية حتى ولو كانت كبيرة، فإذا أنقذها إنسان من غرق أو حرق أو هدم فإنه يكون محسناً وله أجر المحسنين وله ثواب المحسنين، لكن لا يكون محرماً لها بذلك، وهكذا لو أنقذ ذكراً لا يكون أباً له ولا محرماً له ولزوجته ونحو ذلك لا، بل يكون على حاله الأولى إن كان أجنبياً فهو أجنبي وإن كان قريباً فهو قريب، المقصود أن إنقاذ الطفل أو الطفلة أو إنقاذ الكبير أو إنقاذ الكبيرة لا يكون سبباً للمحرمية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7747/هل-تثبت-المحرمية-لمن-انقذ-طفلة-من-الغرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24804.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":10230,"question":"رسالة من تبوك بعث بها مستمع من هناك يقول المرسل (أ. ح. ش) يقول: هل عيال الأخ محرم لزوجة عمهم؟ وهل لها أن تقابلهم وهي متحجبة؟","title":"محارم المرأة من جهة زوجها أصوله وفروعه فقط","answer":"الجواب: ليس أولاد الأخ محرمًا لزوجة عمهم، بل الأخ نفسه ليس محرمًا، أخو الزوج وعم الزوج وأبناء أخيه كلهم ليسوا محارم، كلهم أجناب ليس لها أن تخلو بواحد منهم، وليس لها أن تكشف لهم، بل عليها أن تحتجب عنهم؛ لأنهم ليسوا محارم، الأخ والعم والخال وابن الأخ كل هؤلاء ليسوا محارم كابن العم وابن الخال، وإنما المحارم من الأصهار: أبو الزوج، وجد الزوج، وابن الزوج، وابن بنت الزوج، وابن ابنه، هؤلاء هم المحارم، وأما أخوه وعمه وخاله وابن أخيه ونحوهم فهؤلاء ليسوا محارم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8393/محارم-المراة-من-جهة-زوجها-اصوله-وفروعه-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33506.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":10294,"question":"إذا حرمت علي امرأة، فهل بناتها يحرمن علي؟","title":"هل تحرم البنت بحرمة الأم؟","answer":"الجواب: هذا فيه تفصيل: إن كانت المرأة أختك فبناتها بنات أختك، حرام عليك هي وبناتها؛ لأنك خالهن، أما إذا كانت عمتك أو خالتك فإنها تحرم عليك هي؛ لأنها خالة وعمة لكن لا تحرم بناتها؛ لأن بنات الخالة حل وبنات العمة حل لك أن تتزوج منهن، وهكذا لو كانت زوجة أبيك أو زوجة جدك فإنها محرم لك، لكن بناتها من غير جدك من زوج آخر لسن محارم لك بل أجنبيات، وإنما حرمت هي عليك؛ لأنها زوجة أبيك أو جدك، لكن بناتها من غير أبيك ومن غير جدك لسن محارم لك إن لم يكن بينك وبينهن رضاعة.\nفالمقصود أن هذا فيه تفصيل: فالمرأة التي هي محرم لك تكون بناتها محرماً لك إذا كانت أختاً لك أو زوجةً لأبيك أو زوجة لجدك أو بنتاً لك أو بنت ابن لك فبناتها كذلك محارم، أما إذا كانت خالةً أو عمةً فإن بناتها لسن محارم لك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8467/هل-تحرم-البنت-بحرمة-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31207.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":10418,"question":"المستمع محمد منير باكستاني من باكستان ويعمل في المملكة -الجلة- بعث برسالة يقول فيها: رجل رضع ثدي جدته مع ابنها وعمره سنة -أي: أنه في سن الرضاع- واستمر هذا الرضاع سنة، ثم بعد ذلك تزوج من ابنة عمه، فهل صار هذا الرجل أخًا لعمه من الرضاع أم لا؟ وإذا كان أخًا لعمه هل يجوز زواجه من ابنة عمه؟ لقد أفتى بعض العلماء بعدم صحة هذا الزواج، ثم أفتاه أحدهم بصحة هذا الزواج، علمًا بأن له من ابنة عمه أربعة أو خمسة أولاد، أرجو الإفادة هل هذا الزواج صحيح أم لا؟ وإذا كان غير صحيح فما هو المترتب على ذلك، وما هو وضع الأولاد، أفيدونا جزاكم الله خيرا؟","title":"حكم الزواج بابنة العم إذا رضع الزوج من أم عمه","answer":"الجواب: إذا كان الرضاع ثابتًا بإقرار الجدة وهي ثقة، أو بشهادة بعض الثقات أنها أرضعته خمس مرات فأكثر، ولو كان أقل من السنة، خمس مرات فأكثر تكفي، فإنه يكون ولدًا لها ويكون أخًا لأبيه إذا كانت أم أبيه يكون أخًا لأبيه، ويكون أخًا لأعمامه، وتكون بنت عمه بنت أخيه ليس له زواجها؛ لأن العم صار أخًا والأب صار أخًا، فيكون النكاح باطلًا من ابنة عمه؛ لأنها ابنة أخيه من الرضاعة.\nوقد ثبت عن الرسول ﷺ أنه قيل له: ألا تنكح ابنة حمزة؟ قال: إنها لا تحل لي إنها ابنة أخي من الرضاعة ويحرم من الرضاعة ما يحرم من النسب.\nفالخلاصة: أن هذا الرجل الذي نكح ابنة عمه وقد ثبت الرضاع من جدته له أن نكاحه باطل وأولاده تبعًا له لأجل شبهة النكاح الذي غلطوا فيه، أولاده ينسبون إليه والحمد لله، ولكن يجب عليه مفارقتها وعدم اتصاله بها، وأن يثبت ذلك عند المحكمة حتى تزوج من شاءت بعد العدة، إذا كان الرضاع ثابتًا بإقرار المرأة وهي ثقة يعني: الجدة، أو بشاهد ثقة أو امرأة ثقة تعرف ذلك وتضبط ذلك أنها أرضعته سنة أو أقل من ذلك، والمطلوب خمس رضعات، متى أرضعته خمس رضعات فأكثر كفى، لقول النبي ﷺ لزوجة أبي حذيفة: أرضعي سالمًا خمس رضعات تحرمي عليه، وهي سهلة بنت سهيل بن عمرو قال لها: أرضعي سالما خمس رضعات تحرمي عليه.\nوفي صحيح مسلم عن عائشة رضي الله عنها قالت: كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات فتوفي النبي ﷺ وهي فيما يقرأ من القرآن، وفي رواية الترمذي رحمه الله: والأمر على ذلك. فالواجب على هذا الرجل ما دام رضاعه ثابتًا أن يفارق ابنة عمه؛ لأنها صارت ابنة أخيه وأولاده منها تابعون له من أجل شبهة النكاح، ونسأل الله أن يعوض كل واحد منهم خيرًا من صاحبه، وأن يوفق الجميع لما يرضيه، وإذا كان لم يتعمدها بل عن جهل فنسأل الله أن يعفو عنهما.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8591/حكم-الزواج-بابنة-العم-اذا-رضع-الزوج-من-ام-عمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34104.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":11178,"question":"من الخرج رسالة بعثت بها إحدى المستمعات تقول: المرسلة أم البراء، أم البراء تسأل وتقول: لي أخت من الرضاعة هل يجوز لأمي أن تكشف وجهها لزوجها؟","title":"حكم كشف المرأة لزوج أخت ابنتها من الرضاعة","answer":"الجواب:  إذا كانت أرضعتها أمك، إذا كانت الأم أرضعتها فزوجها زوج بنتها حينئذٍ، إذا كان أرضعتها خمس رضعات أو أكثر في الحولين، فهي بنتها وزوجها زوج البنت، والرسول ﷺ يقول: يحرم من الرضاع ما يحرم من النسب، هي مثل بنت النسب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9360/حكم-كشف-المراة-لزوج-اخت-ابنتها-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37205.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":11185,"question":"من الخرج رسالة بعثت بها إحدى المستمعات تقول: المرسلة أم البراء، أم البراء تسأل وتقول: لي أخت من الرضاعة هل يجوز لأمي أن تكشف وجهها لزوجها؟","title":"حكم كشف المرأة لزوج أخت ابنتها من الرضاعة","answer":"الجواب:  إذا كانت أرضعتها أمك، إذا كانت الأم أرضعتها فزوجها زوج بنتها حينئذٍ، إذا كان أرضعتها خمس رضعات أو أكثر في الحولين، فهي بنتها وزوجها زوج البنت، والرسول ﷺ يقول: يحرم من الرضاع ما يحرم من النسب، هي مثل بنت النسب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9360/حكم-كشف-المراة-لزوج-اخت-ابنتها-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37205.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":11191,"question":"بعد هذا ننتقل إلى ينبع عبر رسالة بعثت بها إحدى الأخوات المستمعات تقول: المرسلة (ع. س) أختنا تقول: إن هناك رجل رضع مع خالتي أخت أمي، فهل يكون لي محرم أم لا؟","title":"حكم محرمية رضاع أخت الأم مع الخالة","answer":"الجواب:  إذا كان رضع من جدتك رضاعًا شرعيًا كاملًا خمس مرات أو أكثر، حال كونه في الحولين، يكون خالًا لك، أخًا لأمك من الرضاعة، إذا كان رضع مع أمك أو مع إحدى خالاتك من جدتك، فإنه يكون خالًا لك أيضًا من الرضاعة، إذا كان الرضاع خمس رضعات فأكثر، وكان حين الرضاع في الحولين لم يفطم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9357/حكم-محرمية-رضاع-اخت-الام-مع-الخالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37202.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":11663,"question":"بنت أخي هل زوجها يكون محرمًا لي؟","title":"حكم محرمية زوج بنت الأخ","answer":"الجواب:  بنت أخيك ليس زوجها محرمًا لك، هذا البنت وبنت بنتك نعم، أما بنت أخيك لا، ولا بنتك أختك، ليس زوجها محرمًا لك، وإنما المحرم زوج البنت، زوج بنت البنت، زوج بنت الابن، هذا محرم، زوج الأم، زوج الجدة محرم -يعني: الذرية والأصول- زوج البنات، وهكذا أزواج بنات البنات وبنات البنين، هؤلاء محارم، وكذلك أزواج الأمهات والجدات محارم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9846/حكم-محرمية-زوج-بنت-الاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29815.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":11895,"question":"هل يجوز أن أقابل أعمام أمي، أو لا يجوز ذلك؟ جزاكم الله خيرًا.","title":"حكم مقابلة المرأة لأعمام وأخوال أبيها وأمها","answer":"الجواب:  أعمام أمك أعمام لك، وهكذا أخوالها أخوالك، عمك عم أبيك وعم أبيك عمك، المقصود عم أبيك، وعم أمك عم لك، وخال أبيك وخال أمك خال لك، فهم محارم، الأخوال لأمك ولجدتك والأعمام لأمك ولجدتك كلهم أعمام لك، وأخوال لك محارم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10079/حكم-مقابلة-المراة-لاعمام-واخوال-ابيها-وامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42516.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":12044,"question":"هل يجوز تقبيل رأس الجدة والخالة والعمة، أو لا يجوز هذا جزاكم الله خيرًا؟","title":"حكم تقبيل رأس الجدة والعمة والخالة","answer":"الجواب: كلهن محارم، الجدة، والخالة، والعمة، والأخت كلهن محارم، فإذا قبل رأس الكبيرة، أو بين عينيها، أو قبل خدها فلا مانع، قد كان الصديق -رضي الله عنه- يقبل عائشة في خدها، وهي ابنته لما دخل عليها وهي مريضة؛ قبلها في خدها.  فهذا لا حرج فيه، وكان النبي ﷺ إذا دخل على فاطمة؛ قامت إليه، وقبلته -عليه الصلاة والسلام- وأخذت بيده وصافحته، وكانت إذا دخل عليها وهو جالس؛ قام إليها، وأخذ بيدها، صافحها وقبلها -عليه الصلاة والسلام، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10229/حكم-تقبيل-راس-الجدة-والعمة-والخالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43313.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":12422,"question":"هل للمرأة أن تكشف على أولاد مطلقها من امرأة أخرى؟","title":"حكم كشف الوجه لأولاد الزوج المطلق","answer":"الجواب: نعم، أولاد زوجها نعم؛ لأنها محرم لهم، زوجة أبيهم، فإذا كان له أولاد من زوجة أخرى؛ فهم محارم، نعم.  المقدم: ولو كانت مطلقة. الشيخ: ولو كانت مطلقة، ولو كان ميتًا هو. المقدم: ما شاء الله، جزاكم الله خيرًا.  الشيخ: الله يقول: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ [النساء:22] يعني: زوجة أبيهم محرمًا لهم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10624/حكم-كشف-الوجه-لاولاد-الزوج-المطلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40212.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":13001,"question":"تقول هذه السائلة: هل يجوز الكشف عند أبي الزوج من الرضاعة، وهل هو من المحارم؟","title":"حكم كشف المرأة عند أب الزوج من الرضاعة","answer":"الجواب:  نعم، أبو الزوج من الرضاعة محرم، كأبيه من النسب، وهكذا ابنه من الرضاعة محرم، نعم.","link":"https://binbaz.org.sa/fatwas/11218/حكم-كشف-المراة-عند-اب-الزوج-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50414.mp3","categories":["النظر والخلوة والاختلاط","المحرمات من النساء","قضايا المرأة"]},{"id":13152,"question":"رجل تزوج بامرأة، وأنجبت له أولادًا، ثم بعد ذلك تبين أنه رضع من أمها عشر رضعات متواليات، هل يطلقها، أم يستمر معها، وهل الأولاد يرثونه، أم ل؟ا مأجورين.","title":"حكم من تزوج بامرأة ثم تبين أنها أخته من الرضاع","answer":"الجواب:  إذا ثبت أنه رضع من أمها بشهادة الثقة من النساء، أو الثقات خمس رضعات، أو أكثر في الحولين، حال كونه في الحولين؛ بان أنها أخت له، فيبطل النكاح، والأولاد يتبعونه، الأولاد نسبهم صحيح؛ لأنهم ولدوا على فراشه على أنها زوجة، فإذا ظهر بعد ذلك أنها رضيعة له؛ لا يضره ذلك، أولاده ينسبون إليه، وهم أولاده، وأولادها. لكن متى ثبت أنها أخته من الرضاع، أو خالته، أو عمته، أو بنت أخيه، أو بنت أخته؛ بطل النكاح، والأولاد أولاده ينسبون إليه؛ لأنه ولدوا على شبهة النكاح، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11406/حكم-من-تزوج-بامراة-ثم-تبين-انها-اخته-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51012.mp3","categories":["الرضاع","المحرمات من النساء","مبطلات النكاح"]},{"id":13240,"question":"تقول هذه السائلة -أيضًا- في أسئلتها: هل صحيح بأن جدتي أم والدتي يكون زوجي لها محرم تسافر معه، وكذلك جدتي والدة أبي؟","title":"جدات الزوجة محرم للزوج","answer":"الجواب: نعم، أمك وجداتك كلهم محارم لزوجك؛ لأن الله قال في المحرمات: وَأُمَّهَاتُ نِسَائِكُمْ [النساء:23] والجدة أم كأمهات النساء، أم المرأة، وإلا جداتها من جهة أبيها، وأمها كلهم محارم للزوج، وهكذا بناتها من زوج سابق، بناتها من زوج سابق محارم لزوجها الحالي، إذا كان قد دخل بها، قد جامعها، فجميع بناتها من أزواجها السابقين محارم لزوجها الجديد إذا دخل بهن، إذا كان قد وطئها؛ لقوله -جل وعلا-: وَرَبَائِبُكُمُ اللَّاتِي فِي حُجُورِكُمْ مِنْ نِسَائِكُمُ اللَّاتِي دَخَلْتُمْ بِهِنَّ [النساء:23] يعني: وطئتموهن، وقوله: فِي حُجُورِكُمْ [النساء:23] وصف أغلبي ليس بشرط، ولو كانت ليست في حجره. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11524/جدات-الزوجة-محرم-للزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51306.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":13465,"question":"بعد ذلك ننتقل إلى رسالة السائل: إبراهيم عبدالعزيز أبو حامد من الرياض، بعث بمجموعة من الأسئلة يبدأ هذه الرسالة بالسؤال الأول ويقول: ما حكم كشف المرأة لوجهها لأبي زوجها من الرضاعة؟","title":"حكم كشف المرأة وجهها لوالد زوجها من الرضاعة","answer":"الجواب: لا حرج، أبو الزوج يصير محرمًا، سواءً نسبًا، أو رضاعة، يقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب أبوه من الرضاع، وابنه من الرضاع محرم، جده من الرضاع، كذلك جد جده، ابن بنته، ابن ابنه، كلهم محارم من النسب والرضاع، نعم.","link":"https://binbaz.org.sa/fatwas/11768/حكم-كشف-المراة-وجهها-لوالد-زوجها-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51713.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":13501,"question":"السائل من أسئلته يقول: ما هي المحرمات من النساء على الرجال؟","title":"المحرمات من النساء","answer":"الجواب: بين الله -جل وعلا- المحرمات في سورة النساء، من قرأ سورة النساء؛ عرف المحرمات في قوله -جل وعلا-: حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالاتُكُمْ وَبَنَاتُ الأَخِ وَبَنَاتُ الأُخْتِ وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23] .. الآية، وبين النبي ﷺ الزيادة على هذا قال: لا يجمع الرجل بين المرأة وعمتها، ولا بين المرأة وخالتها وقال ﷺ: يحرم من الرضاعة ما يحرم من النسب فالأمر واضح، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11815/المحرمات-من-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53104.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":13825,"question":"يقول في سؤال له هل يجوز للرجل أن ينظر أو يصافح أم زوجته؟","title":"حكم مصافحة أم الزوجة","answer":"الجواب: أم زوجته محرم، قال الله جل وعلا: وَأُمَّهَاتُ نِسَائِكُمْ[النساء:23]، بيَّنها في المحارم فله أن ينظر إليها وله أن يصافحها؛ لكن من غير شهوة، مصافحة العادة ونظر العادة من غير شهوة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12192/حكم-مصافحة-ام-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53707.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":13877,"question":"السائلة (ر . م . هـ) من القصيم استعرضنا سؤالاً لها في حلقة سابقة، تقول: لي أخ من الرضاع أسلم عليه وأقبله كأخي فهل ما أفعله صحيح؟ وهل هو محرم لي؟ أرجو منكم الإجابة.","title":"حكم مصافحة الأخ من الرضاعة وتقبيله","answer":"الجواب:  نعم. هو محرم لك، إذا كان الرضاع ثابت فهو محرم لك كأخيك من النسب، ولكي تقبيله بين عينيه أو على أنفه أو على رأسه ومصافحته كأخيك من النسب وكعمك من النسب فهو محرم إذا كان الرضاع ثابت خمس رضعات أو أكثر في الحولين، إذا كان الرضاع ثابت خمس رضعات أو أكثر حال كونه في الحولين فلا بأس، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12278/حكم-مصافحة-الاخ-من-الرضاعة-وتقبيله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50611.mp3","categories":["الرضاع","المحرمات من النساء","قضايا المرأة"]},{"id":13891,"question":"السائلة (ر . م . هـ) من القصيم استعرضنا سؤالاً لها في حلقة سابقة، تقول: لي أخ من الرضاع أسلم عليه وأقبله كأخي فهل ما أفعله صحيح؟ وهل هو محرم لي؟ أرجو منكم الإجابة.","title":"حكم مصافحة الأخ من الرضاعة وتقبيله","answer":"الجواب:  نعم. هو محرم لك، إذا كان الرضاع ثابت فهو محرم لك كأخيك من النسب، ولكي تقبيله بين عينيه أو على أنفه أو على رأسه ومصافحته كأخيك من النسب وكعمك من النسب فهو محرم إذا كان الرضاع ثابت خمس رضعات أو أكثر في الحولين، إذا كان الرضاع ثابت خمس رضعات أو أكثر حال كونه في الحولين فلا بأس، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12278/حكم-مصافحة-الاخ-من-الرضاعة-وتقبيله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50611.mp3","categories":["الرضاع","المحرمات من النساء","قضايا المرأة"]},{"id":13956,"question":"عم الوالدة وخالها هل هم من محارمي؟","title":"محرمية العم والخال","answer":"الجواب: نعم، عمها وخالها من محارمها؛ قاعدة: المحرم كل من تحرم عليه بنسب كخالها وعمها وأبيها أو سبب كالرضاع أو المصاهرة كأب الزوج وابن الزوج هؤلاء هم المحارم، فالخال من المحارم والعم من المحارم، وإن كان خال أبيها، وإن كان خال أمها، وإن كان عم أبيها وعم أمها فإن عم أبيها عم لها، وعم أمها عم لها، وهكذا خال أبيها وخال أمها أخوالًا لها، فهم محارم، وإن علوا كأخي جدها وأخي جدتها هم أخوال لها وأعمام. نعم.","link":"https://binbaz.org.sa/fatwas/12369/محرمية-العم-والخال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60414.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":14007,"question":"في الحقيقية أن أسئلة المستمع مساعد سالم جار النبي المالكي جيدة، لكن هذا السؤال ما أدري كيف خطر على باله يقول فيه: رجل كان له زوجة أنجبت بنت وتزاعل معها وطلقها والبنت معها وتزوج ثانية وهي باقية معه أنجبت ولد - ذكر - كبر الولد وأراد أن يزوجه والده، هل يجوز الولد هذا يأخذ البنت التي من والده أنجبتها الزوجة التي كانت قبل والدته؟","title":"حكم زواج الولد من بنت زوجة والده","answer":"الجواب: يزوج بأخته؟! هذا منكر! لا، هو أخوها سواء كان من أمها أو من أبيها فقط، أخوها لا يتزوجها سواء كان أخًا لها من أبيها أو أخًا لها من أمها أو أخًا لها من أمها وأبيها جميعًا، هذا غريب هذا السؤال.\nالمقصود: أنه لا يجوز له، أما لو كانت البنت من غيره بنتًا له من زوج سابق، فهذا لا بأس، زوج ولده من زوجة أخرى لا بأس أن ينكح بنت زوجته من زوج آخر، أما بنت زوجته منه فهي أخت لولده من الزوجة الأخرى ولا تحل له؛ لأنها أخته.\nالمقدم: شكرًا أثابكم الله.","link":"https://binbaz.org.sa/fatwas/12426/حكم-زواج-الولد-من-بنت-زوجة-والده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_540/54007.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":14021,"question":"المستمع (م. م.ع) من ليبيا بعث برسالة يقول فيها: كما علمت أن مصافحة المرأة الأجنبية حرام، هل يجوز لي مصافحة امرأة خالي؟ وأرجو توضيح المحارم؛ لأن والدتي قالت: إذا لم تصافح امرأة خالك لا أصافحك، هل يجوز طاعتها في ذلك؟","title":"حكم مصافحة زوجة الخال","answer":"الجواب: المصافحة للنساء لا تجوز، قال النبي ﷺ: إني لا أصافح النساء، وقالت عائشة رضي الله عنها: \"ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام\"، ولأن المصافحة للنساء فيها فتنة وخطر كالنظر إليهن، فالواجب عدم مصافحة النساء سوى المحارم، أما المحارم فلا بأس، والمحارم: من يحرم عليك نكاحها؛ كأمك وبنتك وأختك وخالتك وعمتك وبنت أخيك وبنت أختك كما بيَّن الله في كتابه العظيم في سورة النساء حيث قال : حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالاتُكُمْ وَبَنَاتُ الأَخِ وَبَنَاتُ الأُخْتِ وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ ...[النساء:23] الآية. فهؤلاء هن المحارم؛ أمك وجداتك للأب والأم وهكذا بناتك وبنات أولادك وبنات بناتك محارم، وهكذا أخواتك وبناتهن وبنات بناتهن أنت خالهن، وهكذا عماتك محارم وخالاتك محارم، أما بناتهن فلسن محارم لكن خالاتك محارم وعماتك محارم، بنات أخيك وبنات أبناء أخيك وبنات بناتهن كل ذلك محارم، بنات أختك كذلك وبنات بناتهن كل ذلك محارم، وبنات أبناء أختك كلهن محارم، وأمك من الرضاعة وجداتك من الرضاعة وأخواتك من الرضاعة وبناتك من الرضاعة وعماتك من الرضاعة وخالاتك من الرضاعة وبنات أخيك من الرضاعة وبنات أختك من الرضاعة كلهن محارم؛ لقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب. وليس لك أن تصافح زوجة خالك ولا زوجة عمك ولا زوجة أخيك؛ لأنهن لسن محارم، زوجة أخيك وزوجة عمك وخالك لسن محارم، وليس لك أن تطيع أمك في ذلك حتى ولو قالت أمك تصافحها؛ لا تصافحها، فإن الطاعة للوالدين في المعروف لا في المعاصي، قال النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق، فليس لك أن تطيع أباك ولا أمك ولا أميراً ولا عالماً ولا غيرهم في معصية إنما الطاعة في المعروف في المباح، وفق الله الجميع للعلم النافع والعمل الصالح.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12439/حكم-مصافحة-زوجة-الخال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61109.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":14523,"question":"هذه رسالة من السائلة (هـ. ك. ب) من بلدة أرطاوي، تقول: هل يجوز لي أن أكشف وجهي عند زوج ابنتي وأسلم عليه، فقد تزوج لي ثلاث بنات ولم أسلم على واحد من أزواجهم؛ وذلك لأنني أستحي منهم أشد الحياء، ولا أحب أن أكشف وجهي عندهم، هل يجوز لي ذلك أم لا؟","title":"حكم كشف المرأة وجهها أمام أزواج بناتها","answer":"الجواب: لا حرج في ذلك، زوج البنت محرم، فلا بأس أن تكشفي له وجهك، ولا بأس أن تسلمي عليه؛ لأنه محرم؛ زوج البنت وزوج بنت البنت وزوج بنت الابن وزوج الأم وزوج الجدة كلهم محارم، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13006/حكم-كشف-المراة-وجهها-امام-ازواج-بناتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_633/nour_63306.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":15455,"question":"يقول في سؤاله الأول: تزوجت من ابنة خالتي، ولي منها طفلان، وقد علمت الآن أنني قد رضعت مع خالي الذي هو أصغر من أمها، حتى بلغت الفطام، فما العمل الآن في زوجتي هذه؟أفيدونا، بارك الله فيكم.","title":"حكم من تزوج بامرأة ثم تبين أنه رضع من جدتها","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: إذا كان الرضاع المذكور ثابتًا بشهادة الثقات أو الثقة من النساء، أو الثقة من الرجال، على أنك ارتضعت مع خالك من أم خالك، أو أم المرأة التي تزوجتها، فإنك بهذا تكون خالها أيضًا؛ لأنك ارتضعت من جدتها التي هي أم خالك وأم زوجتك، فإذا كان رضاعًا كاملًا خمس مرات فأكثر، فإنها تكون بنت أختك، ويبطل النكاح، ونسأل الله أن يعوض كلًا منكما خيرًا من صاحبه. أما الذرية فذريتك لاحقون بك؛ لأن الوطء باعتقاد النكاح الشرعي، وأنتم معذورون للجهل، فالأولاد أولادك وأولادها ولا حرج عليكما فيما مضى، والمستقبل تفارقها؛ لأنها صارت حينئذٍ بنت أختك، وأنت أخو أمها، نعم. المقدم: لو قدر وفرضنا مثل هذه الحالة وتوفي الزوج قبل أن يعلم هذا الوضع فهل ترث الزوجة؟\nالشيخ: لو توفي ثم بان أنه بهذه المثابة ما يكون زوج يكون النكاح باطل، وليس بينهما توارث.\nالمقدم: ليس بينهما توارث.\nالشيخ: لا ما فيه توارث. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13977/حكم-من-تزوج-بامراة-ثم-تبين-انه-رضع-من-جدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_687/nour_68701.mp3","categories":["الرضاع","المحرمات من النساء","مبطلات النكاح"]},{"id":16103,"question":"تقول السائلة: هل جدود زوجي محارم لي؟","title":"هل جد الزوج محرم؟","answer":"الجواب: نعم جد الزوج محرم، والله يقول: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ [النساء:22]، الجد أب، أبو زوجك محرم، وجده محرم من أبيه، ومن أمه، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14748/هل-جد-الزوج-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57922.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":16283,"question":"إحدى الأخوات المستمعات بعثت برسالة، وضمنتها عددًا من الأسئلة، ورمزت إلى اسمها بالحروف (ع. ف) تقول: إن لي ابن عمة، توفيت والدته وهو ما زال طفلًا صغيرًا، ثم قامت جدتي أم أبي -وهي جدته لأمه- بإرضاعه مع إحدى عماتي، وسؤالي: هل هو محرم لنا، ولا يجوز لنا الزواج منه؛ لأنه رضع مع عمتي، ويكون أخًا لها، وابن أختها، مع العلم أنني أتغطى عنه حتى أعلم الحكم؟","title":"محرمية من رضع من الجدة لبنات ابنها","answer":"الجواب: إذا كان الرضاع شرعيًّا خمس مرات، أو أكثر في حال كونه طفلًا، لم يفطم قبل الحولين؛ فإنه يكون عمًّا لك، يكون أخًا لأبيك ومحرمًا لك؛ لأنها أرضعته الجدة أم أبيك، فيكون عمًّا لك، وعمًّا لأولاد أبيك كلهم، إذا كان الرضاع خمس رضعات، أو أكثر، في الحولين قبل أن يفطم، أما إن كان الرضاع أقل، أو بعد فطامه؛ فلا عبرة به، ولا يؤثر، ولا يكون عمًا لك، نعم. المقدم: جزاكم الله خيرًا، إذًا: عليها أن تتأكد من تفاصيل الرضاع وحينئذٍ .....؟ الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14967/محرمية-من-رضع-من-الجدة-لبنات-ابنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75207.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":16406,"question":"من أحد الإخوة المستمعين اسمه بكري أحمد رسالة، وضمنها جمعًا من الأسئلة، يسأل عن مصافحة عدد من النساء، ويصفهم كالتالي: وجهوني حول مصافحة زوجة الجد هل هي جائزة، أو لا؟","title":"حكم مصافحة زوجة الجد","answer":"الجواب: مصافحة النساء إذا كن من المحارم لا بأس بها، ولا حرج فيها، وزوجة الجد من المحارم، زوجة أبيك، وجدك، وجد جدك كلهن من المحارم، وهكذا زوجة أبنائك.. زوجات أبنائك، وأبناء بناتك، وأبناء بنيك؛ كلهن من المحارم. أما زوجة أخيك فليست من المحارم لا تصافحها، وهكذا زوجة عمك وخالك، وابن عمك؛ كلهن لسن من المحارم، وهكذا جارتك وزوجة جارك كلهن من الأجناب لا تصافح، ولكن لا مانع من السلام، السلام مشروع بالكلام، السلام عليكم... وعليكم السلام! كيف حالكم؟ كيف أولادكم؟ كل هذا طيب، هذا مشروع. أما المصافحة فلا، لا تصافح إلا من كانت محرمًا لك؛ لكونها أختك، أو بنتك، أو أمك، أو عمتك، أو خالتك، أو زوجة أبيك، أو زوجة جدك، أو زوجة ابنك، أو ابن ابنك، أو ابن بنتك، هؤلاء كلهن محارم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15124/حكم-مصافحة-زوجة-الجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75505.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":16430,"question":"أيضًا مصافحة الجد لزوجة ابن ابنه؟","title":"ما حكم مصافحة الجد لزوجة ابن ابنه؟","answer":"الجواب: نعم... محارمه، سواء كان من الرضاع، أو من النسب، وهكذا زوجة أبيه من الرضاع والنسب؛ كلهن محارم، نعم.","link":"https://binbaz.org.sa/fatwas/15127/ما-حكم-مصافحة-الجد-لزوجة-ابن-ابنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75506.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":16836,"question":"يقول في سؤال آخر: إن لي زوجة أرضعتها امرأة في صغرها، وزوجتي تقول لها: هي أمي، والمرضعة تقول لها: هي ابنتي، هل تكون مرضعة زوجتي محرمًا لي؟","title":"الزوج محرم لأم الزوجة من الرضاعة","answer":"الجواب: نعم، إذا كانت أرضعتها خمس رضعات في الحولين؛ فإنها أم زوجتك، يقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب فإذا كانت ثقة المرضعة، وذكرت أنها أرضعتها خمس مرات فأكثر، خمس رضعات في الحولين، فهي محرم لك، أو شهد لها بذلك من هو معروف بالثقة من الرجال، أو النساء، أما قول البنت فقط لا يكفي، لا بد أن تكون المرضعة ثقة، وتشهد برضعات، خمس رضعات فأكثر؛ لأن الرسول ﷺ لما قالت امرأة لعقبة بن الحارث: إني قد أرضعتكم، أرضعتك وزوجتك، قال له النبي ﷺ: دعها؛ كيف وقد قيل ذلك؟. فالمقصود: أنه إذا كانت المدعية للرضاعة ثقة، وذكر أنها أرضعتها خمس رضعات فأكثر، في الحولين؛ فإنها تكون محرمًا لك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15601/الزوج-محرم-لام-الزوجة-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82402.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":16852,"question":"يقول في سؤال آخر: إن لي زوجة أرضعتها امرأة في صغرها، وزوجتي تقول لها: هي أمي، والمرضعة تقول لها: هي ابنتي، هل تكون مرضعة زوجتي محرمًا لي؟","title":"الزوج محرم لأم الزوجة من الرضاعة","answer":"الجواب: نعم، إذا كانت أرضعتها خمس رضعات في الحولين؛ فإنها أم زوجتك، يقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب فإذا كانت ثقة المرضعة، وذكرت أنها أرضعتها خمس مرات فأكثر، خمس رضعات في الحولين، فهي محرم لك، أو شهد لها بذلك من هو معروف بالثقة من الرجال، أو النساء، أما قول البنت فقط لا يكفي، لا بد أن تكون المرضعة ثقة، وتشهد برضعات، خمس رضعات فأكثر؛ لأن الرسول ﷺ لما قالت امرأة لعقبة بن الحارث: إني قد أرضعتكم، أرضعتك وزوجتك، قال له النبي ﷺ: دعها؛ كيف وقد قيل ذلك؟. فالمقصود: أنه إذا كانت المدعية للرضاعة ثقة، وذكر أنها أرضعتها خمس رضعات فأكثر، في الحولين؛ فإنها تكون محرمًا لك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15601/الزوج-محرم-لام-الزوجة-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82402.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":16887,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات اسمها أنداء كراسًا فيما يبدو، تقول في أحد أسئلتها: إن أمي قد أرضعت عمتي شقيقة والدي، وعمتي في عمر يناهز السنة والنصف، وبلغت عدد الرضعات المشبعات خمسًا فما فوق، فهل يحق لابن عمتي أن يتزوج بي أو لا؟ جزاكم الله خيرًا، وإن حصل الزواج فهل الانفصال واجب مؤكد في هذه الحالة؟ أجيبوني أثابكم الله، وجعلنا جميعًا من عباده الصالحين.","title":"حكم الزواج من ابن الأخت من الرضاعة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإذا كان الواقع هو ما ذكرته السائلة، وأن أمها أرضعت عمتها خمس رضعات، أو أكثر، فإن ابن العمة يكون ابن أخت، وتكون العمة أختًا لك، ويكون ولدها ابن أختك، وأنت خالته؛ فالنكاح باطل حينئذ إن كنت قد أصبت في السؤال، ولا بد من عرض الموضوع على المحكمة لديكم -إذا كانت الوالدة موجودة- حتى يسألها الوالد عن حقيقة الرضاع، أو تحضر عندي إن كانت في الرياض حتى أسألها. المقصود: أنه إذا كان الواقع هو ما ذكرت: أن أمك أرضعت عمتك خمس رضعات، فأكثر؛ فإنها تكون أختًا لك، ويكون ولدها ابن أختك، وأنت خالته، والنكاح باطل حينئذ لو نكحكِ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15640/حكم-الزواج-من-ابن-الاخت-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76501.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":17299,"question":"المستمعة أم يوسف لها هذا السؤال نختم به هذه الحلقة تقول: هل يجوز للأم من الرضاعة أن تكشف وجهها عن زوج ابنتها من الرضاعة؟ وكذلك إذا كان عندها أولاد، فهل تكشف لهم؟","title":"زوج البنت من الرضاعة محرم لأمها","answer":"الجواب: نعم، زوج بنتها من الرضاعة محرم، زوج ابنتها من الرضاعة، وزوج أمها من الرضاعة محرم لها، تكشف له.","link":"https://binbaz.org.sa/fatwas/16142/زوج-البنت-من-الرضاعة-محرم-لامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59312.mp3","categories":["الرضاع","المحرمات من النساء","قضايا المرأة"]},{"id":17531,"question":"تقول السائلة أيضًا: هل يجوز للمرأة أن تقابل عم والدها؟","title":"ما حكم مقابلة المرأة عم والدها؟","answer":"الجواب: عم والدها عم لها، عم الوالد عم لها.. محرم لها، عم أبيها وعم جدها عم لها، وعم أمها وعم جدتها عم لها محرم تقابلهم وتصافحهم ولا تحتجب عنهم؛ لأن عم الإنسان عم أبيك عمك، وعم جدك عمك، وهكذا الخال، خال أمها خالها وخال جدتها خالها وخال أبيها خالها.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16451/ما-حكم-مقابلة-المراة-عم-والدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77507.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":17672,"question":"هذا سائل محمد طويلع يقول في هذا السؤال يا سماحة الشيخ: الإخوة في برنامج نور على الدرب لي مجموعة من الأسئلة يقول: هل يجوز للمرأة أن تصافح خال أمها؟ وهل يعتبر محرمًا لها؟","title":"محرمية خال الأم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالخال محرم، خال الأم خال الجدة محرم، خال أمك خال لك وخال أبيك خال لك، فخال أبيك وخال أمك وخال جدتك وخال جدك كلهم أخوال لك محارم. نعم.","link":"https://binbaz.org.sa/fatwas/16603/محرمية-خال-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59501.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":17714,"question":"تقول الأخت السائلة أم محمد من مدينة الزلفي في آخر أسئلتها: سماحة الشيخ! هل علي إثم إذا لم أكشف وجهي عن زوج ابنتي؟ جزاكم الله خيرًا.","title":"مشروعية كشف المرأة وجهها عند زوج ابنتها","answer":"الجواب: المشروع لك كشفه، التعبد بهذا ما يجوز؛ لأن هذا خلاف ما شرع الله، زوج بنتك محرم لك؛ لأن الله قال: وَأُمَّهَاتُ نِسَائِكُمْ [النساء:23]، المقصود أنه محرم، فالحاصل أن أم الزوجة محرم للزوج فلا تغطي عنه، بل اكشفي له الوجه وخذي برخص الله، الرسول ﷺ يقول: عليكم برخص الله التي رخص لكم وهذا تنطع وتكلف لا ينبغي ولا يجوز. نعم.\nالمقدم: أحسن الله إليكمـ وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16668/مشروعية-كشف-المراة-وجهها-عند-زوج-ابنتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59525.mp3","categories":["النظر والخلوة والاختلاط","المحرمات من النساء"]},{"id":17759,"question":"هذه سائلة للبرنامج (العوفي ) قرية قصيبة تقول: سماحة الشيخ! هل زوجة الخال من المحارم أم لا؛ لأنني سمعت أن زوجة العم ليست من المحارم، ولكن زوجة الخال من المحارم الذي لا يجوز الزواج بها بعد وفاة زوجها أو طلاقها منه؟","title":"زوجة الخال ليست من المحارم","answer":"الجواب: زوجة الخال وزوجة العم وزوجة الأخ لسن من المحارم، إذا مات زوجها أو طلقها وخرجت من العدة؛ جاز أن ينكحها ولد أخته لا بأس، زوجة الأخ، الأخ أقرب زوجته ما هي بمحرم، المحرم زوجة الأب والجد والابن، أما زوجة الأخ وزوجة الخال وزوجة العم، فلسن محارم، بل هو أجنبي ..، زوجة خاله أجنبية، زوجة عمه أجنبية، زوجة أخيه أجنبية، ليس له أن يخلو بها، وليس لها أن تكشف له. نعم.\nالمقدم: حفظكم الله يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16729/زوجة-الخال-ليست-من-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59617.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":17760,"question":"تقول السائلة: هل يجوز لأزواج بنات أختي أن أكشف لهم وأسلم عليهم بوجهي، أم لا يجوز؟","title":"زوج بنت الأخت ليس محرمًا","answer":"الجواب: لست محرمًا لهم، أنت خالتها خالة بنات أختك، فأزواج ... ليس محرمًا لك، زوج أختك ليس محرمًا لك ولست محرمًا له، إنما هو زوج أمك زوج جدتك ما يخالف زوج بنتك ما يخالف لا بأس، أما زوج الأخت وزوج بنت الأخت لا ليس محرم.\nالمقدم: حفظكم الله يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16732/زوج-بنت-الاخت-ليس-محرما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59618.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":17969,"question":"هل يجوز أن أقابل خال أمي وعمها؟ أم أنهم غير محارم؟","title":"محرمية خال الأم وعمها","answer":"الجواب: خال أمك وعم أمك محرمان، عم أمك عم لك وخالها خال لك، وهكذا عم أبيك وخال أبيك كلاهما محارم لك وإن علا الجد حتى جد أبيك، وحتى جد أمك وجدت أمك.\nفالمقصود أن خال الإنسان يكون خالًا لذريته، فخال أمك خال لك ولذريتك، وعم أمك عم لك ولذريتك، وهكذا خال أبيك وعم أبيك خال لك ولذريتك وعم لك ولذريتك وإن بعدن. نعم.","link":"https://binbaz.org.sa/fatwas/17008/محرمية-خال-الام-وعمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84815.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":17975,"question":"هل يجوز أن أقابل خال أمي وعمها؟ أم أنهم غير محارم؟","title":"محرمية خال الأم وعمها","answer":"الجواب: خال أمك وعم أمك محرمان، عم أمك عم لك وخالها خال لك، وهكذا عم أبيك وخال أبيك كلاهما محارم لك وإن علا الجد حتى جد أبيك، وحتى جد أمك وجدت أمك.\nفالمقصود أن خال الإنسان يكون خالًا لذريته، فخال أمك خال لك ولذريتك، وعم أمك عم لك ولذريتك، وهكذا خال أبيك وعم أبيك خال لك ولذريتك وعم لك ولذريتك وإن بعدن. نعم.","link":"https://binbaz.org.sa/fatwas/17008/محرمية-خال-الام-وعمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84815.mp3","categories":["المحرمات من النساء","قضايا المرأة"]},{"id":18023,"question":"المستمعة (ف. س) من الباحة بعثت برسالة وضمنتها سؤالًا مطولًا بعض الشيء عن الرضاع، تقول: أرضعت والدتي ابنة خالتي مع أخي الأكبر، ولكنه توفي وهو مولود وبعدما كبرت ابنة خالتي وتزوجت أنجبت ولداً فأرضعته والدتي معي ثم أرضعت شقيقته الصغرى مع شقيقي الأصغر مني.والسؤال هو: هل يجوز لي أن أكشف على والد أخي من الرضاع؟ وهل يجوز الكشف على أبناء خالتي الذين هم أشقاء أختنا من الرضاع وأخوال أخي من الرضاع؟","title":"حكم كشف المرأة لوالد الأخ من الرضاعة","answer":"الجواب: تكشفين للرضيع الذي هو أخوك أما أبوه ليس محرمًا لك إذا كان أجنبي ما تكشفين له، تكشفين للرضيع الذي أرضعته والدتك يكون أخًا لك من الرضاعة، وأما أبوه إذا أرضعت الأم ابنة شخص فالرضيع هو الذي أخ لك إذا كان خمس رضعات فأكثر، أما أبوه الأجنبي ليس محرمًا لك. أما لو كان ابن خالك خالك محرمًا ولو ما أرضعت أمك ابنه، خالك محرم وخال أمك وخال جدتك محرم لك، لكن إذا أرضعت أمك شخصًا من الناس فهو الذي يكون أخًا لك إذا كان الرضاع خمس رضعات في الحولين أو أكثر، أما أبوه الأجنبي سواء كان ابن عم أو ابن خال أو من الجيران ما يكون محرمًا لك؛ لأنه ليس رضيعًا هو الرضيع ولده. فالرضيع هو الذي يكون محرمًا لك، أما إخوته الذين ما أرضعتهم أمك وأبوه هؤلاء ليسوا محارم لك، المحرم الشخص الذي أرضعته أمك خمس رضعات أو أكثر في الحولين، أما إخوته الذين لم يرضعوا وهم أجناب أو أبوه أو جده فليسوا محارم لك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17067/حكم-كشف-المراة-لوالد-الاخ-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85012.mp3","categories":["المحرمات من النساء","الرضاع","قضايا المرأة"]},{"id":18356,"question":"هذا السائل علي الطيب، مقيم بالمملكة العربية السعودية، يقول: رجل تم عقده على امرأة، ولم يدخل بها وتوفي هذا الرجل، فهل يجوز لابنه من بعد وفاة أبيه أن يتزوج هذه المرأة؟","title":"حكم الزواج بمن عقد عليها الأب ولم يدخل بها","answer":"الجواب: بعقد الزواج عليها حرمت على أبنائه، وعلى آبائه، ما يجوز .","link":"https://binbaz.org.sa/fatwas/17407/حكم-الزواج-بمن-عقد-عليها-الاب-ولم-يدخل-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91323.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":18381,"question":"تقول في قضية أخرى: فتاة رضعت من امرأةٍ وهي صغيرة رضعتين، وجاء ابن هذه المرأة وأراد أن يخطب هذه الفتاة، مع العلم أنها رضعت مع أخيه الأصغر منه، فهل يجوز أن تتزوج هذه الفتاة من هذا الشاب؟ أم لا؟ جزاكم الله خيرًا.","title":"حكم الزواج بامرأة رضعت من أم الزوج رضعتين","answer":"الجواب: الرضعتان لا تحرمان، يقول النبي ﷺ: لا تحرم الرضعة، ولا الرضعتان ويقول ﷺ لسهلة بنت سهيل: \"أرضعي سالمًا خمس رضعات تحرمي عليه\"، وتقول عائشة رضي الله عنها في الحديث الصحيح: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك\". فالرضعتان لا تحرمان، ولا حرج عليه في الزواج، لكن إذا ترك هذا من باب الاحتياط؛ لأن بعض أهل العلم يرى الرضعة الواحدة تحرم، من باب ترك المشتبه حسن، يقول النبي ﷺ: دع ما يريبك، إلى ما لا يريبكإذا ترك هذا احتياطًا، وبعدًا عن الشبهة؛ فلا حرج، هذا حسن طيب. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17438/حكم-الزواج-بامراة-رضعت-من-ام-الزوج-رضعتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73213.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":19004,"question":"رسالة من أحد الإخوة المستمعين يقول المرسل: إبراهيم أحمد ذيب من اليمن، أخونا إبراهيم له جمع من الأسئلة من بينها سؤال يقول: رجل عقد على امرأة، ولم يدخل بها سواء توفي أو طلقها،  هل يجوز لابنه أن يتزوجها أم تكون من المحرمات عليه؟ جزاكم الله خيرًا.","title":"حكم زواج الابن من مطلقة أبيه التي لم يدخل بها","answer":"الجواب: إذا تم العقد للرجل على امرأة عقدًا شرعيًا؛ فإنها تكون محرمة على جميع ذريته، وعلى أبيه، وأجداده، ولو لم يدخل بها سواء مات أو طلق؛ لقول الله جل وعلا: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ[النساء:22] هذا عام، نكاح العقد، ونكاح الدخول، ولقوله جل وعلا: وَحَلائِلُ أَبْنَائِكُمُ[النساء:23] زوجات الأبناء الَّذِينَ مِنْ أَصْلابِكُمْ[النساء:23] فحلائل الأبناء محرمات على الآباء، كما أن حلائل الآباء محرمة على الأبناء، على أبنائهم، وأبناء أبنائهم، وأبناء بناتهم، وزوجات البنين محرمة على الآباء، والأجداد سواء كان الابن ابنك أو ابن بنتك. وقوله: مِنْ أَصْلابِكُمْ[النساء:23] احترازًا من الأدعياء كانوا في الجاهلية يتبنون، بعض الناس يربونهم ويتبنونهم، هؤلاء ليسوا بأبناء وإن تبنوهم، وزوجاتهم غير محرمات. والنبي ﷺ تزوج زينب بنت حجش وقد طلقها زيد بن حارثة، وكان النبي ﷺ قد تبناه في الجاهلية، ثم أمره الله أن يدعى لأبيه فقال: ادْعُوهُمْ لِآبَائِهِمْ[الأحزاب:5]، وتزوج النبي ﷺ مطلقته زينب حتى يعلم الناس أنه لا حرج في تزوج مطلقات الأدعياء، الأبناء الأدعياء. أما ابنك من الرضاعة، وابنك من النسب؛ فزوجته حرام عليك، وزوجة أبيه من الرضاعة ومن النسب حرام عليه. وهكذا زوجات أجدادك من النسب؛ والرضاعة، وهكذا زوجات أبنائك من النسب؛ والرضاعة، وأبناء بناتك كلهن محرمات، ولو لم يدخل الزوج بالزوجة، ولو لم يخل بها، ما دام تم العقد الشرعي كفى. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18168/حكم-زواج-الابن-من-مطلقة-ابيه-التي-لم-يدخل-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_795/nour_79509.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":19385,"question":"رسالة بعث بها لنا مستمع من خليص، سمى نفسه فتى الطلعة، يسأل ويقول: ابنة أخي إذا كان لها بنت هل لي الزواج بها؟","title":"حكم الزواج ببنت بنت الأخ","answer":"الجواب: بنت أخيك وبنت بنت أخيك محرم، ليس لك الزواج ببنت أخيك ولا بناتها ولو نزلن، بنت أخيك وبنت بنت أخيك، وبنت ابن أخيك، وبنت بنت بنت ابن أخيك كلهم محارم، أنت عمهن جميعًا ولو نزلن. فليس لك الزواج بواحدة منهن بإجماع المسلمين؛ لأن الله جل وعلا حرم في المحرمات بنات الأخ.\nوبنات الأخ تشمل القريبات والبعيدات، بنات الأخ وبنات ابن الأخ، وبنات بنات ابن الأخ، يعني: وإن نزلن. فالحاصل أن بنات الأخ وبنات ابن الأخ وإن نزلن محرمات على عمهن، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18606/حكم-الزواج-ببنت-بنت-الاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93413.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":19559,"question":"تقول: هل زوجة الأب المطلقة يجوز لها أن تكشف على أولاد زوجها الذي طلقها؟","title":"محرمية أولاد الزوج لزوجة أبيهم المطلقة","answer":"الجواب: نعم، لها أن تكشف عنهم؛ لأنها زوجة أبيهم، والله يقول: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ[النساء:22] فزوجة أبيهم محرم لهم، ولو بعد الطلاق والموت، ولو بعد طلاقه لها أو موته، هي محرم لهم. نعم.","link":"https://binbaz.org.sa/fatwas/18807/محرمية-اولاد-الزوج-لزوجة-ابيهم-المطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94706.mp3","categories":["الرضاع","المحرمات من النساء"]}]
